#!/bin/zsh
# End-to-end check on the synthetic documents in tests/fixtures, driving a real browser with playwright-cli.
# Usage: tests/e2e.sh   (site/, built from src/, is served by Herd at http://diff-tracker.test)
# Fixtures are generated by: uv run tests/fixtures/make.py
set -u
FX=${0:A:h}/fixtures
# drops files (absolute paths) on a CSS selector, like a user dragging them from Finder
DROP="const drop = async (sel, paths) => { await page.evaluate(() => { if (!document.querySelector('#probe')) { const i = document.createElement('input'); i.type = 'file'; i.multiple = true; i.id = 'probe'; i.hidden = true; document.body.append(i); } }); await page.setInputFiles('#probe', paths); await page.evaluate(sel => { const dt = new DataTransfer(); for (const f of document.querySelector('#probe').files) dt.items.add(f); const t = document.querySelector(sel); for (const type of ['dragenter', 'dragover', 'drop']) t.dispatchEvent(new DragEvent(type, { dataTransfer: dt, bubbles: true, cancelable: true })); }, sel); await page.waitForTimeout(1500); };"
S="raff-e2e-$(LC_ALL=C tr -dc 'a-z0-9' </dev/urandom | head -c 6)"
URL=${URL:-http://diff-tracker.test/}
# Herd serves site/, built from src/
if [[ $URL == http://diff-tracker.test/ ]]; then node ${0:A:h}/../scripts/build.mjs >/dev/null || exit 1; fi
playwright-cli -s=$S open $URL >/dev/null
fail=0
check() { # name fileA fileB js-assertion-on-S
  local out
  if [[ ! -f $2 || ! -f $3 ]]; then echo "skip $1 (file mancante)"; return; fi
  out=$(playwright-cli -s=$S run-code "async page => { await page.goto('$URL'); const ins = page.locator('.drop input'); await ins.nth(0).setInputFiles('$2'); await ins.nth(1).setInputFiles('$3'); await page.waitForFunction(() => !document.querySelector('#ws').hidden || !document.querySelector('#dlg').hidden, null, {timeout: 30000}); await page.waitForTimeout(800); $4 }" 2>&1 | sed -n "/### Result/{n;p;}")
  if [[ $out == '"ok"' ]]; then echo "ok   $1"; else echo "FAIL $1: $out"; fail=1; fi
}
# one-time explanation of the revisions selector: remembered per browser in localStorage
forget_hint() { playwright-cli -s=$S run-code "async page => { await page.goto('$URL'); await page.evaluate(() => localStorage.removeItem('raffronto-revisions-hint')); }" >/dev/null; }
HINT="const hint = () => page.evaluate(() => { const h = document.querySelector('#revHint'); if (!h || h.hidden) return null; const seg = document.querySelector('.revs .seg').getBoundingClientRect(); const a = h.querySelector('.coach-arrow').getBoundingClientRect(); const ax = a.left + a.width / 2; return { near: ax > seg.left && ax < seg.right && a.top >= seg.bottom - 2 && a.top - seg.bottom < 16, text: h.textContent }; }); const load = async (a, b) => { await page.goto('$URL'); const ins = page.locator('.drop input'); await ins.nth(0).setInputFiles(a); await ins.nth(1).setInputFiles(b); await page.waitForFunction(() => !document.querySelector('#ws').hidden, null, {timeout: 30000}); await page.waitForTimeout(800); };"
forget_hint
check "spiegazione revisioni: non compare senza revisioni" "$FX/immagine-con.docx" "$FX/immagine-senza.docx" \
  "$HINT return (await hint()) === null ? 'ok' : 'compare';"
check "spiegazione revisioni: compare una volta sola, vicino al selettore" "$FX/statute-revisions.docx" "$FX/statute.docx" \
  "$HINT const A = '$FX/statute-revisions.docx', B = '$FX/statute.docx'; const first = await hint(); await page.getByRole('button', { name: 'Ho capito' }).click(); await page.waitForTimeout(300); const closed = await hint(); const saved = await page.evaluate(() => localStorage.getItem('raffronto-revisions-hint')); await load(A, B); const again = await hint(); await page.evaluate(() => localStorage.removeItem('raffronto-revisions-hint')); await load(A, B); const shown = await hint(); await page.keyboard.press('Escape'); await page.waitForTimeout(300); const esc = await hint(); return first && first.near && /Accettate/.test(first.text) && /Rifiutate/.test(first.text) && !closed && saved && !again && shown && !esc ? 'ok' : JSON.stringify({ first, closed, saved, again, shown: !!shown, esc: !!esc });"
check "regolamento v1 vs v2: simili, con differenze" "$FX/regulation-v1.docx" "$FX/regulation-v2.docx" \
  "return page.evaluate(() => { const S = window.__raffronto; return S.result.sim > .6 && S.hunks.length > 10 && document.querySelectorAll('.chg').length === S.view.length ? 'ok' : JSON.stringify({sim: S.result.sim, n: S.hunks.length}); });"
check "statuto: revisioni rifiutate = originale" "$FX/statute-revisions.docx" "$FX/statute.docx" \
  "const before = await page.evaluate(() => window.__raffronto.hunks.length); await page.getByRole('button', {name: 'Rifiutate'}).click(); await page.waitForTimeout(1200); const after = await page.evaluate(() => window.__raffronto.hunks.length); return before > 5 && after === 0 ? 'ok' : JSON.stringify({before, after});"
check "pdf: due modifiche" "$FX/agreement-v1.pdf" "$FX/agreement-v2.pdf" \
  "return page.evaluate(() => { const S = window.__raffronto; return S.hunks.length === 2 && document.querySelectorAll('.hl').length > 5 ? 'ok' : JSON.stringify({n: S.hunks.length}); });"
check "file diversi: avviso" "$FX/regulation-v1.docx" "$FX/statute.docx" \
  "return page.evaluate(() => !document.querySelector('#dlg').hidden ? 'ok' : 'no dialog');"
check "sync scroll + hover" "$FX/regulation-v1.docx" "$FX/regulation-v2.docx" \
  "await page.mouse.move(300, 600); for (let i = 0; i < 5; i++) await page.mouse.wheel(0, 600); await page.waitForTimeout(500); await page.locator('.pane[data-side=\"0\"] mark.mk').nth(30).hover(); await page.waitForTimeout(200); return page.evaluate(() => { const sc = document.querySelectorAll('.scroller'); const lit = [0, 1].map(i => sc[i].querySelectorAll('.lit').length); return sc[1].scrollTop > 1000 && lit[0] > 0 && lit[1] > 0 ? 'ok' : JSON.stringify({b: sc[1].scrollTop, lit}); });"
check "hover resta acceso tra due righe della stessa modifica" "$FX/regulation-v1.docx" "$FX/regulation-v2.docx" \
  "const gap = await page.evaluate(async () => { const m = [...document.querySelectorAll('.pane[data-side=\"1\"] mark.mk')].find(m => m.getClientRects().length >= 2); if (!m) return null; m.scrollIntoView({ block: 'center' }); await new Promise(r => setTimeout(r, 300)); const r = [...m.getClientRects()]; return { h: +m.dataset.h, x0: r[0].left + 5, y0: r[0].top + r[0].height / 2, x: Math.max(r[0].left, r[1].left) + 30, y: (r[0].bottom + r[1].top) / 2 }; }); if (!gap) return 'nessuna modifica su piu righe'; await page.mouse.move(gap.x0, gap.y0); await page.waitForTimeout(100); await page.mouse.move(gap.x, gap.y, { steps: 4 }); await page.waitForTimeout(150); const h = await page.evaluate(() => window.__raffronto.hover); return h === gap.h ? 'ok' : JSON.stringify({ want: gap.h, got: h });"
check "il più recente va a destra, e si può invertire" "$FX/statute-revisions.docx" "$FX/statute.docx" \
  "const names = () => page.evaluate(() => window.__raffronto.sides.map(s => s.file.name)); const first = await names(); const n1 = await page.evaluate(() => window.__raffronto.hunks.length); await page.getByRole('button', { name: 'Inverti i documenti' }).click(); await page.waitForTimeout(1200); const second = await names(); const n2 = await page.evaluate(() => window.__raffronto.hunks.length); return first[1] === 'statute-revisions.docx' && second[0] === 'statute-revisions.docx' && n1 === n2 ? 'ok' : JSON.stringify({ first, second, n1, n2 });"
check "pdf firmato: firma aggiunta riconosciuta" "$FX/agreement-v2-signed.pdf" "$FX/agreement-v2-countersigned.pdf" \
  "return page.evaluate(() => { const S = window.__raffronto; const v = S.hunks.filter(h => h.vis); const heads = [...document.querySelectorAll('.pane-head')].map(e => e.textContent); const items = [...document.querySelectorAll('.chg')].map(e => e.textContent); const boxes = document.querySelectorAll('.pane[data-side=\"1\"] .hl.vis').length; return v.length === 1 && v[0].type === 'add' && items.some(t => t.includes('Mario Rossi')) && boxes === 1 && /1 firma/.test(heads[0]) && /2 firme/.test(heads[1]) ? 'ok' : JSON.stringify({ v: v.map(h => h.vis && h.vis.label), items, heads, boxes }); });"
check "pdf non firmato vs firmato: prima firma riconosciuta" "$FX/agreement-v2.pdf" "$FX/agreement-v2-signed.pdf" \
  "return page.evaluate(() => { const S = window.__raffronto; const v = S.hunks.filter(h => h.vis); const heads = [...document.querySelectorAll('.pane-head')].map(e => e.textContent); const items = [...document.querySelectorAll('.chg')].map(e => e.textContent); return S.result.sim === 1 && S.hunks.length === 1 && v.length === 1 && v[0].type === 'add' && items.some(t => t.includes('Luca Bianchi')) && !/firm/.test(heads[0]) && /1 firma/.test(heads[1]) ? 'ok' : JSON.stringify({ n: S.hunks.length, items, heads }); });"
check "word: immagine tolta riconosciuta" "$FX/immagine-con.docx" "$FX/immagine-senza.docx" \
  "return page.evaluate(() => { const S = window.__raffronto; const v = S.hunks.filter(h => h.vis); return v.length === 1 && S.hunks.length === 1 && document.querySelectorAll('.page.docx img').length === 1 && document.querySelectorAll('.vis[data-h]').length === 1 ? 'ok' : JSON.stringify({ n: S.hunks.length, v: v.length, imgs: document.querySelectorAll('.page.docx img').length }); });"
check "word con carta intestata vs pdf stampato" "$FX/letterhead-declaration.docx" "$FX/letterhead-declaration.pdf" \
  "return page.evaluate(() => { const S = window.__raffronto; const docx = document.querySelector('.page.docx'); return S.result.sim > .97 && !S.hunks.some(h => h.vis) && docx.querySelector('img') && /officinebrenta/.test(docx.textContent) ? 'ok' : JSON.stringify({ sim: S.result.sim, n: S.hunks.length, vis: S.hunks.filter(h => h.vis).length, img: !!docx.querySelector('img') }); });"
check "trascino 1 file su un lato: lo sostituisce" "$FX/regulation-v1.docx" "$FX/regulation-v2.docx" \
  "$DROP await drop('.pane[data-side=\"1\"] .scroller', ['$FX/immagine-con.docx']); return page.evaluate(() => window.__raffronto.sides[1].file.name === 'immagine-con.docx' && window.__raffronto.sides[0].file.name === 'regulation-v1.docx' ? 'ok' : JSON.stringify(window.__raffronto.sides.map(s => s.file.name)));"
check "trascino 2 file: chiede conferma per un nuovo confronto" "$FX/regulation-v1.docx" "$FX/regulation-v2.docx" \
  "$DROP await drop('.pane[data-side=\"0\"] .scroller', ['$FX/immagine-con.docx', '$FX/immagine-senza.docx']); const asked = await page.evaluate(() => !document.querySelector('#dlg').hidden && /nuovo confronto/i.test(document.querySelector('#dlg').textContent)); await page.click('#dlgGo'); await page.waitForTimeout(1500); const names = await page.evaluate(() => window.__raffronto.sides.map(s => s.file.name).sort().join()); return asked && names === 'immagine-con.docx,immagine-senza.docx' ? 'ok' : JSON.stringify({ asked, names });"
check "trascino 3 file: avvisa che non si può" "$FX/regulation-v1.docx" "$FX/regulation-v2.docx" \
  "$DROP await drop('.pane[data-side=\"0\"] .scroller', ['$FX/immagine-con.docx', '$FX/immagine-senza.docx', '$FX/statute-revisions.docx']); const t = await page.evaluate(() => ({ toast: document.querySelector('#toast').hidden ? '' : document.querySelector('#toast').textContent, names: window.__raffronto.sides.map(s => s.file.name).join() })); await page.goto('$URL'); await drop('.drop', ['$FX/immagine-con.docx', '$FX/immagine-senza.docx', '$FX/statute-revisions.docx']); const t2 = await page.evaluate(() => document.querySelector('#toast').hidden ? '' : document.querySelector('#toast').textContent); return /due file/.test(t.toast) && t.names.includes('regulation-v1.docx') && /due file/.test(t2) ? 'ok' : JSON.stringify({ t, t2 });"
# download as PDF through the print dialog: window.print is stubbed, the print layout is saved with page.pdf (print media, backgrounds off like the dialog default)
OUT=${OUT:-/tmp/raffronto-print}; mkdir -p $OUT
PRINT="const printAs = async (layout, path, want) => { const title0 = await page.evaluate(() => { window.__printed = null; window.print = () => { window.__printed = document.title; }; return document.title; }); await page.click('#printBtn'); await page.click('#printMenu [data-layout=\"' + layout + '\"]'); await page.waitForFunction(() => window.__printed != null, null, { timeout: 180000 }); await page.emulateMedia({ media: 'print' }); const r = await page.evaluate(() => { const root = document.querySelector('#printRoot'); const shown = s => [...document.querySelectorAll(s)].some(e => getComputedStyle(e).display !== 'none'); const mk = root.querySelector('.slot mark.mk, .slot .hl:not(.ghost)'); return { title: window.__printed, sheets: root.querySelectorAll('.sheet').length, marks: root.querySelectorAll('.slot mark.mk, .slot .hl, .slot .caret').length, mkBg: mk ? getComputedStyle(mk).backgroundColor : '', bodyBg: getComputedStyle(document.body).backgroundColor, filter: getComputedStyle(root.querySelector('.slot .page')).filter, chrome: shown('.topbar, #ws'), list: root.querySelectorAll('.print-list .chg').length, want: document.querySelectorAll('#list .chg').length, listH: root.querySelector('.print-list').getBoundingClientRect().height, blank: [...root.querySelectorAll('.slot img')].filter(i => !i.complete || !i.naturalWidth).length, uneven: [...root.querySelectorAll('.sheet')].map(s => [...s.querySelectorAll('.fit')]).filter(f => f.length === 2).filter(f => { const z = f.map(e => e.firstElementChild.getBoundingClientRect().width / e.firstElementChild.offsetWidth), t = f.map(e => e.getBoundingClientRect().top); return Math.abs(z[0] - z[1]) > .001 || Math.abs(t[0] - t[1]) > 1; }).length, kind: window.__raffronto.sides[1].kind, rl: { inline: root.querySelectorAll('.slot del.rl').length, notes: root.querySelectorAll('.rl-note').length, links: root.querySelectorAll('.rl-link').length, plain: [...root.querySelectorAll('.slot del.rl, .rl-note del')].filter(e => !/line-through/.test(getComputedStyle(e).textDecorationLine) || !/^rgb\\((1[6-9]\\d|2\\d\\d), \\d\\d?, /.test(getComputedStyle(e).color)).length, out: [...root.querySelectorAll('.rl-note')].filter(n => { const s = n.closest('.sheet').getBoundingClientRect(), b = n.getBoundingClientRect(); return b.top < s.top - 1 || b.bottom > s.bottom + 1 || b.right > s.right + 1; }).length, want: window.__raffronto.hunks.filter(h => !h.vis && h.type !== 'move' && h.a1 > h.a0).length } }; }); const buf = await page.pdf({ path, preferCSSPageSize: true }); r.pages = (buf.toString('latin1').match(/\\/Type\\s*\\/Page(?!s)/g) || []).length; r.kb = Math.round(buf.length / 1024 / r.pages); r.empty = await page.evaluate(() => [...document.querySelectorAll('#printRoot .page.pdf canvas')].filter(c => { const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data; for (let i = 0; i < d.length; i += 4 * 97) if (d[i] < 128) return false; return true; }).length); await page.emulateMedia({ media: null }); await page.evaluate(() => window.dispatchEvent(new Event('afterprint'))); r.after = await page.evaluate(() => ({ title: document.title, root: !!document.querySelector('#printRoot') })); const rl = layout === 'redline', flow = rl && r.kind === 'docx'; const ok = /^Raffronto - /.test(r.title) && (flow ? r.sheets >= want : r.sheets === want) && r.pages > r.sheets && r.pages <= r.sheets + 1 + Math.ceil(r.listH / 700) && !r.uneven && r.kb < 100 && !r.empty && (!rl || (!r.rl.plain && !r.rl.out && (flow ? r.rl.inline === r.rl.want && !r.rl.notes : r.rl.notes === r.rl.want && r.rl.links === r.rl.want && !r.rl.inline))) && r.marks > 0 && !/^(transparent|rgba\\(0, 0, 0, 0\\))/.test(r.mkBg) && r.bodyBg === 'rgb(255, 255, 255)' && r.filter === 'none' && !r.chrome && r.list === r.want && !r.blank && !r.after.root && r.after.title === title0; return ok ? null : { layout, ...r }; }; const printAll = async name => { const n = await page.evaluate(() => window.__raffronto.layout.R.map(r => r.pages.length)); const bad = []; for (const [k, want] of [['redline', n[1]], ['both', Math.max(...n)], ['0', n[0]], ['1', n[1]]]) { const r = await printAs(k, '$OUT/' + name + '-' + k + '.pdf', want); if (r) bad.push(r); } return { n, bad }; };"
check "scarica pdf (word): affiancati, solo originale, solo nuova versione" "$FX/regulation-v1.docx" "$FX/regulation-v2.docx" \
  "$PRINT const btn = await page.evaluate(() => !document.querySelector('#printBtn').hidden); const res = await printAll('word'); await page.click('#newBtn'); const gone = await page.evaluate(() => document.querySelector('#printBtn').hidden); return btn && gone && !res.bad.length ? 'ok' : JSON.stringify({ btn, gone, ...res });"
check "scarica pdf (pdf, tema scuro): stampa chiara con evidenziazioni" "$FX/agreement-v2-signed.pdf" "$FX/agreement-v2-countersigned.pdf" \
  "$PRINT await page.evaluate(() => { document.documentElement.dataset.theme = 'dark'; }); const res = await printAll('pdf'); const theme = await page.evaluate(() => document.documentElement.dataset.theme); await page.evaluate(() => { document.documentElement.dataset.theme = localStorage.getItem('raffronto-theme') || 'light'; }); return theme === 'dark' && !res.bad.length ? 'ok' : JSON.stringify({ theme, ...res });"
check "scarica pdf (word sintetico): versione finale con le parti tolte in linea" "$FX/print-old.docx" "$FX/print-new.docx" \
  "$PRINT const res = await printAll('fx-word'); return !res.bad.length ? 'ok' : JSON.stringify(res);"
check "scarica pdf (pdf sintetico): leggero, stessa scala, parti tolte a margine" "$FX/print-old.pdf" "$FX/print-new.pdf" \
  "$PRINT const res = await printAll('fx-pdf'); return !res.bad.length ? 'ok' : JSON.stringify(res);"
# download as Word with tracked changes: the file is saved from the download and checked outside the browser
# (tests/check_tracked.py: valid zip and XML, revisions consistent with the differences, accept all = right, reject all = left)
WORD="const wordExport = async path => { await page.click('#printBtn'); const [dl] = await Promise.all([page.waitForEvent('download', { timeout: 60000 }), page.click('#printMenu [data-export=\"docx\"]')]); await dl.saveAs(path); return page.evaluate(name => { const S = window.__raffronto, txt = S.hunks.filter(h => !h.vis); return { name, ins: txt.reduce((n, h) => n + h.b1 - h.b0, 0), del: txt.reduce((n, h) => n + h.a1 - h.a0, 0), insHunks: txt.filter(h => h.b1 > h.b0).length, delHunks: txt.filter(h => h.a1 > h.a0).length, texts: S.sides.map(s => s.kind === 'pdf' ? s.model.text : null), note: document.querySelector('#printMenu [data-export] span').textContent }; }, dl.suggestedFilename()); };"
word_check() { # name fileA fileB left-ref right-ref [js run before the download] [js check on the result r]
  if [[ ! -f $2 || ! -f $3 ]]; then echo "skip word con revisioni: $1 (file mancante)"; return; fi
  local out res
  out=$(playwright-cli -s=$S run-code "async page => { await page.goto('$URL'); const ins = page.locator('.drop input'); await ins.nth(0).setInputFiles('$2'); await ins.nth(1).setInputFiles('$3'); await page.waitForFunction(() => !document.querySelector('#ws').hidden, null, {timeout: 30000}); await page.waitForTimeout(800); ${6:-} $WORD const r = await wordExport('$OUT/$1.docx'); ${7:-} return JSON.stringify(r); }" 2>&1 | sed -n "/### Result/{n;p;}; /### Error/{n;p;}")
  print -r -- "$out" > $OUT/$1.json
  res=$(uv run -q ${FX:h}/check_tracked.py $OUT/$1.docx --browser $OUT/$1.json --left $4 --right $5 2>&1)
  if [[ $res == ok* ]]; then echo "ok   word con revisioni: $1 ${res#ok }"; else echo "FAIL word con revisioni: $1: $res"; fail=1; fi
}
word_check docx-pair "$FX/tracked-old.docx" "$FX/tracked-new.docx" "$FX/tracked-old.docx" "$FX/tracked-new.docx" "" \
  "if (r.name !== 'tracked-new - con revisioni.docx') throw new Error('nome ' + r.name);"
word_check docx-revised-accepted "$FX/tracked-old.docx" "$FX/tracked-new-revised.docx" "$FX/tracked-old.docx" "$FX/tracked-new-revised.docx"
word_check docx-revised-rejected "$FX/tracked-old.docx" "$FX/tracked-new-revised.docx" "$FX/tracked-old.docx" "$FX/tracked-new-revised.docx:reject" \
  "await page.getByRole('button', { name: 'Rifiutate' }).click(); await page.waitForTimeout(1200);" \
  "if (!/rifiutate/.test(r.note)) throw new Error('nota ' + r.note);"
word_check docx-numbered "$FX/regulation-v1.docx" "$FX/regulation-v2.docx" "$FX/regulation-v1.docx" "$FX/regulation-v2.docx"
word_check pdf-pair "$FX/tracked-old.pdf" "$FX/tracked-new.pdf" browser browser "" \
  "if (!/formattazione/.test(r.note)) throw new Error('nota ' + r.note);"
playwright-cli -s=$S close >/dev/null
# share by link (own browser session, local only): see tests/share.sh
URL=$URL zsh ${0:A:h}/share.sh || fail=1
# installable app and offline use: see tests/pwa.sh
URL=$URL zsh ${0:A:h}/pwa.sh || fail=1
# link preview, slogan, 16bit credit, search engine files, visit statistics: see tests/marketing.sh
URL=$URL zsh ${0:A:h}/marketing.sh || fail=1
# pages for each profession, languages: see tests/pages.sh; the whole app in English: see tests/english.sh
URL=$URL zsh ${0:A:h}/pages.sh || fail=1
URL=$URL zsh ${0:A:h}/english.sh || fail=1
# privacy policy and terms of use, linked from the footer: see tests/legal.sh
URL=$URL zsh ${0:A:h}/legal.sh || fail=1
# page addresses without a trailing slash, and the redirect from the old ones: see tests/urls.sh
URL=$URL zsh ${0:A:h}/urls.sh || fail=1
# desktop app download page, picked for the visitor's system: see tests/download.sh
URL=$URL zsh ${0:A:h}/download.sh || fail=1
exit $fail
